```tsx
import { createCollection } from '@tanstack/react-db'
import { supabaseCollectionOptions } from '@supabase-labs/tanstack-db'
import { z } from 'zod'

const todosSchema = z.object({
  id: z.number(),
  title: z.string(),
  completed: z.boolean(),
})

export const todos = createCollection(
  supabaseCollectionOptions({
    tableName: 'todos',
    keys: ['id'],
    schema: todosSchema,
    supabase,
    realtime: true,
  })
)
